'use strict';
const fs=require('node:fs'),assert=require('node:assert/strict');
const path=require('node:path');
const html=fs.readFileSync(path.join(__dirname,'index.html'),'utf8');
const pkg=JSON.parse(fs.readFileSync(path.join(__dirname,'package.json'),'utf8'));
assert.equal(pkg.version,'1.0.109');
const label=html.match(/<label\b[^>]*for="nanoTenderAmount108"[^>]*>([\s\S]*?)<\/label>/);
assert.ok(label,'payment field label is required');
assert.equal(label[1].trim(),'المبلغ المدفوع');
assert.ok(!label[0].includes('data-i18n'),'unknown translation key must not replace Arabic label on startup');
assert.ok(!html.includes('data-i18n="nano_received_amount_108"'));
assert.ok(!html.includes('onclick="nanoCheckoutPayFull104()"'));
assert.ok(!html.includes('onclick="nanoOpenCreditPicker107()"'));
assert.ok(html.includes('id="nanoTenderAmount108"'),'user must retain freely entered amount');
assert.ok(html.includes('id="checkoutPaidAmount"'),'accounting hidden field must remain');
assert.ok(html.includes('src="nano-flex-payment-108.js"'),'partial credit & change frontend must remain active');
const bridge=fs.readFileSync(path.join(__dirname,'browser-bridge.js'),'utf8');
assert.ok(bridge.includes("if (channel === 'process-sale')"));
assert.ok(bridge.includes('nano_checkout_operation_id'));
assert.ok(bridge.includes('sale.cash_change_amount'));
console.log('PASS: checkout label is المبلغ المدفوع and no raw i18n token; flexible sales, credit and change preserved');
